from pathlib import Path
import json,hashlib,datetime
ROOT=Path(__file__).resolve().parents[1]
HOME_AGENT=ROOT.parents[1]
protocol=json.loads(Path(r'~\mop_fei100\reports\fei-2026-10-11\EXECUTION_PROTOCOL.json').read_text())
statement='For B05 quadratic bent point surgery with even k>=4 and r>=2k controls, min_i B_i/Inf_i is the data-coordinate ratio in REPORT.md (B05-X) at k=4 and psi(2^(-r)(1-2^(-k/2)+2^(-k))) at k>=6. Its sharp uniform supremum is psi(57/262144)<2+7/1024. For the A062 k-control activation of a balancing sign times M=2^(k-1) quadratic bent factors, the balancing-sign coordinate uniquely minimizes the ratio, which equals (1-q)Phi(1,v)+Phi((1-q)^2,q^2 v)/q with q=2^(-k),v=4^(-M). Its sharp uniform supremum is (5/4)log2(5)-2<1 and its limit is zero.'
hyp=['Uniform physical cube; actual Boolean signs; entropy in bits','B_i=H(S_i|S_without_i); relevant-coordinate minimum only','The exact canonical origin-point quadratic bent families defined in REPORT.md','Finite k,r in the stated domains; no restriction-closure assumption']
sha=hashlib.sha256(json.dumps({'statement':statement,'hypotheses':hyp},sort_keys=True,separators=(',',':')).encode()).hexdigest()
claim={'claim_id':'A089-EXACT-EXISTENTIAL-ERASURE-REPAIR','version':1,'exact_statement':statement,'hypotheses':hyp,'statement_sha256':sha,'contributors':['A089'],'proof_source':{'run_id':ROOT.name,'path':'REPORT.md','sections':'3-5'},'proof_dependencies':[],'review_records':[],'status':'AUTHOR_PROVED_PENDING_INDEPENDENT_REVIEW','supersedes':[],'refutes':[],'first_unproved_line':None,'next_consumers':['A023','A026','A064','A090','A094','B18','B20']}
assert set(claim)==set(protocol['required_per_run']['claim_fields'])
(ROOT/'CLAIMS.json').write_text(json.dumps([claim],indent=2)+'\n')
progress={'protocol_revision':protocol['revision'],'run_id':ROOT.name,'stream':'B18','packet_id':'A089','gap_id':'G-R-SELECT','attempt_id':'A089-EXISTENTIAL-FAMILY-REPAIR-1','method':'Analytic coordinate-pair entropy enumeration and exact independent integer Walsh/boundary verification','mathematical_delta':'Exact minima and sharp uniform family constants on both lead-selected all-dimensional counterfamilies; B05 minimizing type changes at k=6, A062 best ratio tends to zero. Universal FEI remains open.','deliverable_status':'COMPLETE_LOCAL_ARTIFACT','mathematical_status':'FAMILY_REPAIR_PROVED_PENDING_INDEPENDENT_REVIEW','claim_versions_used':[],'claims_created_or_changed':[{'claim_id':claim['claim_id'],'version':1}],'source_artifacts':['REPORT.md','CLAIMS.json','code/check.py','out/FROZEN_SPEC.json','out/FROZEN_SPEC_v1.1.json','out/CHECK.json','out/CHECK_v1_overrun.json','out/FIRST_CHECK_FAILURE.md','out/SOURCE_INVENTORY.json','out/PAPERS.json'],'next_consumers':claim['next_consumers'],'next_action':'Compute the full A062 sign-first stopping-tree ledger on both unbalanced activated bent children, with labelled nonreuse and terminal reserves; A090/A094 independently reconstruct this repair.','stagnant_substantive_attempts':0,'blockers':['Independent review and supervisor adoption pending; universal restriction closure and terminal payment unpaid'],'packet_ids':['A089']}
# Protocol annotates the final name as 'packet_ids (one primary ID, for compatibility)'.
# Its compatibility.run_delta rule supplies the actual JSON key packet_ids.
expected_progress={field.split(' (')[0] for field in protocol['required_per_run']['progress_fields']}
assert set(progress)==expected_progress
for name in ['PROGRESS.json','PACKET_DELTA.json']:(ROOT/name).write_text(json.dumps(progress,indent=2)+'\n')
report=(ROOT/'REPORT.md').read_text()
for field in protocol['required_per_run']['report_fields']:assert '## '+field in report
check=json.loads((ROOT/'out'/'CHECK.json').read_text());assert check['failed']==0 and check['assertions_passed']==150
stamp=datetime.datetime.now(datetime.timezone.utc).isoformat()
(HOME_AGENT/'STATUS.md').write_text('STATE: A089 exact existential repairs proved locally: B05 sharp K<2+7/1024; A062 sharp K=(5/4)log2(5)-2<1; 150 exact checks; review pending, full FEI OPEN.\nNEXT: A090/A094 review; compute A062 sign-first child/tree erasure with labelled influence and terminal reserves.\n')
with (HOME_AGENT/'WORKLOG.md').open('a',encoding='utf-8') as fp:fp.write('\n'+stamp+' A089 stage: followed B18 lead; repaired every-coordinate obstruction by exact family minima. First Walsh check exposed omitted nonempty-control activation fibers; corrected full formula. Five actual Boolean tables, all coordinates, 150 exact assertions passed. Uncached v1 runtime 202.310s exceeded pilot budget; preserved result and added cached bounded rerun. Sharp constants and complete proof saved, pending independent review. Full FEI OPEN.\n')
with (HOME_AGENT/'LEARNED.md').open('a',encoding='utf-8') as fp:fp.write('\nA089 repair: Activation changes the empty-core Fourier coefficient in EVERY control fiber, not only the constant fiber. For B05 even k>=4,r>=2k, the exact minimum is data at k=4 and controls at k>=6; sharp family K=psi(57/262144)<2+7/1024, limiting ratio 2. The rare selector still diverges. For A062, balancing sign minimizes, exact ratio (1-q)Phi(1,v)+Phi((1-q)^2,q^2v)/q with v=4^(-2^(k-1)); sharp K=Phi(1,1/4)<1 and ratio tends to 0. Root good-coordinate bounds do not justify restriction closure or deleting leaf reserves. Memoize repeated exact entropy packets before a truth-table pilot.\n')
receipt={'created_utc':stamp,'schema_checks':'claim_fields, progress_fields, report_fields and PACKET_DELTA equality PASS; packet_ids annotation normalized per compatibility.run_delta','validation':check,'local_only':True,'files':[]}
assert json.loads((ROOT/'PROGRESS.json').read_text())==json.loads((ROOT/'PACKET_DELTA.json').read_text())
for p in sorted(ROOT.rglob('*')):
    if p.is_file() and p.name!='RECEIPTS.json':receipt['files'].append({'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()});assert p.stat().st_size<20*1024*1024
(ROOT/'out'/'RECEIPTS.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps({'saved':str(ROOT),'claim_count':1,'assertions':check['assertions_passed'],'runtime_seconds':check['runtime_seconds'],'schema_checks':'PASS','files':len(receipt['files'])}))
